const PADDY_BASE = 0.43;                 // 중립 논비중(지정 평균 ~43%) — 순식량 평형 유지(총식량 변화 시 광산·인구 흔들림). 강가=이득/내륙=손해
const FOOD_GROUP = { food: 'grain', fish: 'fish', meat: 'meat', fruit: 'fruit', vegetable: 'veg', mushroom: 'forage' };
